/**
 * Test fixtures.
 *
 * Everything here is built in memory at test time, with one deliberate
 * exception: the encrypted PDFs. pdf-lib (and the @cantoo/pdf-lib fork we
 * decrypt with) can read encryption but not write it, so those three cannot be
 * produced from inside a test run. They are generated by
 * scripts/generate-encrypted-fixtures.py and committed.
 *
 * Multi-page fixtures give every page a distinct size so a test can assert
 * *which* pages survived an operation, not merely how many. Asserting page
 * counts alone would pass for a split that returned the wrong pages.
 */
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { PDFDocument } from "@cantoo/pdf-lib";

const FIXTURE_DIR = join(dirname(fileURLToPath(import.meta.url)), "fixtures");

/** Password on the committed encrypted fixtures. Mirrors the generator script. */
export const FIXTURE_PASSWORD = "correct-horse";

/** Page sizes used by makePdf and by the committed encrypted fixtures. */
export const pageSizeFor = (index: number): [number, number] => {
  const side = 200 + index * 100;
  return [side, side];
};

/** Identify a page by its size, so tests can assert page *identity*. */
export const pageIndexOf = (width: number): number => Math.round((width - 200) / 100);

/** Build an unencrypted PDF whose pages are individually identifiable. */
export async function makePdfBytes(pageCount: number): Promise<Uint8Array> {
  const doc = await PDFDocument.create();
  for (let i = 0; i < pageCount; i++) doc.addPage(pageSizeFor(i));
  return doc.save();
}

export async function makePdfFile(pageCount: number, name = "sample.pdf"): Promise<File> {
  const bytes = await makePdfBytes(pageCount);
  return new File([bytes], name, { type: "application/pdf" });
}

/** Read back the ordered page sizes of a produced PDF. */
export async function pageWidthsOf(source: Blob | Uint8Array): Promise<number[]> {
  const bytes = source instanceof Uint8Array ? source : new Uint8Array(await source.arrayBuffer());
  const doc = await PDFDocument.load(bytes);
  return doc.getPages().map((p) => Math.round(p.getWidth()));
}

/** The page indices, in order, that a produced PDF actually contains. */
export async function pageIndicesOf(source: Blob | Uint8Array): Promise<number[]> {
  return (await pageWidthsOf(source)).map(pageIndexOf);
}

/** Bytes that are definitively not a PDF — for error-path tests. */
export function makeCorruptPdfFile(name = "broken.pdf"): File {
  return new File([new Uint8Array([0x00, 0x01, 0x02, 0x03, 0x04])], name, {
    type: "application/pdf",
  });
}

// ---------------------------------------------------------------------------
// Encrypted fixtures (committed; see the module docstring)
// ---------------------------------------------------------------------------

export type EncryptedFixture =
  | "encrypted-rc4-128.pdf"
  | "encrypted-aes-256.pdf"
  | "encrypted-empty-password.pdf";

export function encryptedPdfFile(which: EncryptedFixture): File {
  const bytes = new Uint8Array(readFileSync(join(FIXTURE_DIR, which)));
  return new File([bytes], which, { type: "application/pdf" });
}

// ---------------------------------------------------------------------------
// Images
// ---------------------------------------------------------------------------

const PNG_1X1 =
  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==";

const JPEG_1X1 =
  "/9j/4AAQSkZJRgABAQEAYABgAAD/2wBDAAgGBgcGBQgHBwcJCQgKDBQNDAsLDBkSEw8UHRofHh0aHBwgJC4nICIsIxwcKDcpLDAxNDQ0Hyc5PTgyPC4zNDL/wAALCAABAAEBAREA/8QAFAABAAAAAAAAAAAAAAAAAAAACf/EABQQAQAAAAAAAAAAAAAAAAAAAAD/2gAIAQEAAD8AKp//2Q==";

const bytesFromBase64 = (b64: string): Uint8Array =>
  Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));

/**
 * `type` is settable because browsers hand back an empty MIME type for some
 * pickers and drag-drop sources — the case the audit's P1-15 covers, where a
 * valid image is rejected as "unsupported".
 */
export function pngFile(name = "image.png", type: string = "image/png"): File {
  return new File([bytesFromBase64(PNG_1X1)], name, { type });
}

export function jpegFile(name = "image.jpg", type: string = "image/jpeg"): File {
  return new File([bytesFromBase64(JPEG_1X1)], name, { type });
}

// ---------------------------------------------------------------------------
// DOCX
// ---------------------------------------------------------------------------

const MINIMAL_DOCX =
  "";

/** Minimal valid .docx: one Heading 1 and one body paragraph. */
export function docxFile(name = "sample.docx"): File {
  return new File([bytesFromBase64(MINIMAL_DOCX)], name, {
    type: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  });
}
